window.__v=(()=>{const g=window.__game,P=g.P,dt=1/30,cl=(v,a,b)=>v<a?a:v>b?b:v,ad=(a,b)=>{let d=a-b;while(d>Math.PI)d-=2*Math.PI;while(d<-Math.PI)d+=2*Math.PI;return d;};
 const V={g,P,
