  walk(x,z,secs,stop){const F=g.makeField(true);g.flow(F,x,z,600);g.BOT.on=true;let t=0;for(;t<secs;t+=dt){const d=Math.hypot(x-P.x,z-P.z);if(d<(stop||.6))break;
