  drive(x,z,secs,o){o=o||{};const k=P.car,F=g.makeField(true);g.flow(F,x,z,1400);g.BOT.on=true;let t=0,dist=0,top=0,lx=k.x,lz=k.z;
   for(;t<secs;t+=dt){const d=Math.hypot(x-k.x,z-k.z);if(d<(o.stop||8))break;let fd=g.flowDir(F,k.x,k.z);
     // look a few cells ahead along the field
     let px=k.x,pz=k.z;for(let s=0;s<4;s++){const q=g.flowDir(F,px,pz);px+=q.x*3;pz+=q.z*3;}const wx=px-k.x,wz=pz-k.z;
     const want=Math.atan2(-wx,-wz),e=ad(want,k.yaw),sp=Math.hypot(k.vx,k.vz);g.BOT.s=cl(-e*2.2,-1,1);g.BOT.f=sp>(o.max||14)?0:Math.abs(e)>.9&&sp>6?-.6:1;g.BOT.sprint=false;
     g.sim(1,dt);dist+=Math.hypot(k.x-lx,k.z-lz);lx=k.x;lz=k.z;top=Math.max(top,sp);}
