     g.BOT.s=cl(-e*2.4,-1,1);g.BOT.f=sp>(max||20)||(Math.abs(e)>.7&&sp>7)?0:1;g.sim(1,dt);dist+=Math.hypot(k.x-lx,k.z-lz);lx=k.x;lz=k.z;top=Math.max(top,sp);}
