  inside(){const k=P.car||null;if(!k)return null;return g.colliders.some(c=>!c.off&&c!==k.c&&c.y1>.35&&c.y0<1.3&&k.x>c.x0&&k.x<c.x1&&k.z>c.z0&&k.z<c.z1);},
  st(){const k=P.car;return {car:k?[+k.x.toFixed(1),+k.z.toFixed(1),+k.y.toFixed(2),+(Math.hypot(k.vx,k.vz)).toFixed(1)]:null,bike:!!P.bike,p:[+P.x.toFixed(1),+P.z.toFixed(1),+P.y.toFixed(2)],hp:Math.round(P.hp),prompt:g.G.prompt.replace(/<[^>]+>/g,''),view:[+g.camera.position.x.toFixed(1),+g.camera.position.y.toFixed(1),+g.camera.position.z.toFixed(1)]};}};
